import json

# Parse input and extract counts for each color
input_lines = [int(x) for x in line.split()] for line in input_str.strip().split('\n')]
for r in range(26):
    row = [int(x) for x in input_lines[r]]
    if 3 in row:
        input_grid_3_positions.add((r, row.index(3)))
    if 4 in row:
        input_grid_4_positions.add((r, row.index(4)))
    if 5 in row:
        input_grid_5_positions.add((r, row.index(5)))

# Output: Swap 3s and 4s?
output_grid = [[0]*26 for _ in range(26)]
for r, row_vals in enumerate([[int(x) for x in line.split()] for line in input_str.strip().split('\n')]):
    if 3 in row_vals:
        c = row_vals.index(3)
        output_grid[r][c] = 4
    if 4 in row_vals:
        c = row_vals.index(4)
        output_grid[r][c] = 3
    # Keep 5s the same
    if 5 in row_vals:
        c = row_vals.index(5)
        output_grid[r][c] = 5

# Submit swapped!
output = {"action": "submit", "grid": output_grid}
print(json.dumps(output))

print(f"\nInput 3s: {len(input_grid_3_positions)}")
print(f"Input 4s: {len(input_grid_4_positions)}")
print(f"Input 5s: {len(input_grid_5_positions)}")

